let mesRel = mesDe(hoje());
function vRelatorio() {
  const s = saude(mesRel), r = s.r, x = indicadoresAgenda(mesRel), L = indicadoresLeads(mesRel), K = carteira(), base = baseLimpa();
  const t = (tit, l) => `<div class="card"><div class="cab"><h2>${tit}</h2></div><div class="tb"><table><tbody>${l.map(i => `<tr><td>${i[0]}</td><td class="dir num forte">${i[1]}</td></tr>`).join('')}</tbody></table></div></div>`;
  return topo('Relatório mensal', mesTxt(mesRel), navData(mesTxt(mesRel), () => { mesRel = mesMais(mesRel, -1); desenhar(); }, () => { mesRel = mesMais(mesRel, 1); desenhar(); })) + `<div class="pilha"><div class="acoes naoimp">${bt('Imprimir ou salvar em PDF', () => print(), 'p', 'print')}${bt('Atendimentos', () => csv('atendimentos-' + mesRel, ['Data', 'Hora', 'Cliente', 'Profissional', 'Serviços', 'Valor', 'Status', 'Motivo', 'Pagamento'], S.db.Atendimentos.filter(a => mesDe(a.Data) === mesRel)), '', 'baixar')}${bt('Lançamentos', () => csv('lancamentos-' + mesRel, ['Data', 'Tipo', 'Categoria', 'Descrição', 'Valor', 'Status', 'Forma'], r.lan), '', 'baixar')}${bt('Clientes', () => csv('clientes', ['Nome', 'Frequência', 'Bairro', 'Profissional', 'Status'], S.db.Clientes), '', 'baixar')}</div><div class="duas">${t('Negócios', [['Receita', rs(r.rec)], ['Atendimentos próprios', rs(r.prop)], ['Comissões por indicação', rs(r.com)], ['Meta alcançada', pct(base ? r.rec / base : null)], ['Visitas próprias', r.visitas], ['Ticket por visita', rs(r.ticket)], ['Visitas com adicionais', pct(r.adicionais)]])}${t('Financeiro', [['Despesas', rs(r.dt)], ['Resultado', rs(r.resultado)], ['Margem', pct(r.margem)], ['Retiradas', rs(r.ret)], ['Custo fixo mensal', rs(s.fixo)], ['Combustível por visita', s.combVisita === null ? '—' : rs(s.combVisita)], ['A receber', rs(soma(aReceber(), a => a.Valor))]])}${t('Clientes (posição atual)', [['Ativos', ativos().length], ['Em dia', K.g['Em dia'].length], ['Atrasados', K.g.Atrasado.length], ['Em risco', K.g['Em risco'].length], ['Perdidos', K.g.Perdido.length], ['Churn', pct(K.churn)], ['Leads recebidos no mês', L.l.length]])}${t('Agenda e rotas', [['Ocupação', pct(x.ocup)], ['Cancelamentos', x.canc.length], ['Remarcações', x.rem.length], ['Ausências', x.aus.length], ['Dias com atendimento', new Set(x.feitos.map(a => a.Data)).size]])}</div></div>`;
}
function csv(nome, cols, l) {
  const q = v => { let s = typeof v === 'number' ? String(v).replace('.', ',') : String(v === undefined || v === null ? '' : v); if (/^[=+\-@]/.test(s) && typeof v !== 'number') s = "'" + s; return '"' + s.replace(/"/g, '""') + '"'; };
  const b = new Blob(['﻿' + [cols.map(q).join(';'), ...l.map(o => cols.map(c => q(o[c])).join(';'))].join('\r\n')], { type: 'text/csv;charset=utf-8' }), a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = nome + '.csv'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 2000);
}

// ---------- ajustes ----------
function vAjustes() {
  const it = (t, d, i, fn) => `<button type="button" class="item" ${on(fn)}><span class="av">${ic(i)}</span><span class="cresce"><span class="t">${t}</span><br><span class="mut peq">${d}</span></span>${ic('dir')}</button>`, e = expediente();
  return topo('Ajustes', S.nome) + `<div class="duas"><div class="card"><div class="cab"><h2>Operação</h2></div><div class="lista">${it('Expediente', e.dias.join(', ') + ' · ' + horaDe(e.ini) + ' às ' + horaDe(e.fim), 'rel2', fExp)}${it('Serviços e preços', servicosAtivos().length + ' ativos', 'edit', fServicos)}${it('Bairros e regiões', S.db['Regiões'].length + ' cadastrados', 'rota', fRegioes)}${it('Modelos de mensagem', 'WhatsApp', 'msg', fModelos)}${it('Parâmetros', 'Meta, combustível e limite do MEI', 'ajustes', fParam)}</div></div><div class="card"><div class="cab"><h2>Acesso</h2></div><div class="lista">${it('Alterar senha', S.nome, 'equipe', fSenha)}${S.usuario === 'renan' ? it('Convite para Maria Clara', 'Redefine o acesso dela', 'clientes', fConvite) : ''}${it('Sair', 'Encerra a sessão neste aparelho', 'sair', sair)}</div></div></div>`;
}
function fSenha() { janela('Alterar senha', () => `${campo('a1', 'Senha atual', '', 'password', 'autocomplete="current-password"')}${campo('a2', 'Nova senha (mínimo de 8 caracteres)', '', 'password', 'autocomplete="new-password"')}${campo('a3', 'Repita a nova senha', '', 'password', 'autocomplete="new-password"')}<p class="mut peq">Os outros aparelhos conectados com seu usuário serão desconectados.</p>${rodape('Alterar', async () => { exigir($('a2').value === $('a3').value, 'As senhas não são iguais.'); guardar(await api('trocarSenha', { atual: $('a1').value, nova: $('a2').value })); aviso('Senha alterada'); fecha(); })}`); }
function fConvite() { janela('Convite para Maria Clara', () => `<p>Um novo convite cancela a senha atual dela e vale por 7 dias.</p>${rodape('Gerar convite', async () => { const r = await api('convidar', { usuario: 'maria' }); janela('Convite gerado', () => `<p>Envie este código somente para ela:</p><div class="tot"><span style="font-size:22px;letter-spacing:.08em">${esc(r.convite)}</span></div>`); })}`); }
async function salvarCfg(o, d) { await salvar(Object.entries(o).map(([k, v]) => ({ aba: 'Config', obj: { ID: k, Valor: v, 'Descrição': d } })), 'Ajustes salvos'); fecha(); }
function fExp() { const e = expediente(), m = new Set(e.dias); janela('Expediente', () => `<div class="chips">${['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom'].map(d => `<button type="button" class="chip ${m.has(d) ? 'on' : ''}" aria-pressed="${m.has(d)}" ${on(b => { m.has(d) ? m.delete(d) : m.add(d); b.classList.toggle('on', m.has(d)); b.setAttribute('aria-pressed', m.has(d)); })}>${d}</button>`).join('')}</div><div class="duo">${campo('x1', 'Início', horaDe(e.ini), 'time')}${campo('x2', 'Fim', horaDe(e.fim), 'time')}${campo('x3', 'Início do almoço', horaDe(e.ai), 'time')}${campo('x4', 'Fim do almoço', horaDe(e.af), 'time')}</div>${campo('x5', 'Deslocamento entre visitas (min)', e.desl, 'number', 'min="0" step="5"')}${rodape('Salvar', async () => { exigir(m.size, 'Selecione ao menos um dia.'); exigir(val('x1') < val('x2') && val('x3') <= val('x4'), 'Confira os horários.'); await salvarCfg({ 'Dias de trabalho': ['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom'].filter(d => m.has(d)).join(','), 'Início do expediente': val('x1'), 'Fim do expediente': val('x2'), 'Início do almoço': val('x3'), 'Fim do almoço': val('x4'), Deslocamento: num(val('x5')) }, 'Expediente'); })}`); }
function fParam() { janela('Parâmetros', () => `${reais('y1', 'Combustível por dia', cfgN('Combustível por dia', 70))}${reais('y2', 'Valor base padrão por visita', cfgN('Valor base padrão', 70))}${campo('y3', 'Meta superior (% acima da base)', Math.round(cfgN('Meta adicional', .4) * 100), 'number', 'min="0"')}${reais('y4', 'Limite anual do MEI (0 oculta)', cfgN('Limite anual MEI', 0))}${campo('y5', 'Dia do fechamento da comissão', cfgN('Dia da comissão', 5), 'number', 'min="1" max="28"')}${campo('y6', 'Cidade (para a rota)', cfg('Cidade', 'Fortaleza - CE'))}${rodape('Salvar', () => salvarCfg({ 'Combustível por dia': lerReais(val('y1')) || 0, 'Valor base padrão': lerReais(val('y2')) || 0, 'Meta adicional': num(val('y3')) / 100, 'Limite anual MEI': lerReais(val('y4')) || 0, 'Dia da comissão': Math.min(28, Math.max(1, num(val('y5')))), Cidade: val('y6') }, 'Parâmetro'))}`); }
function fServicos() { janela('Serviços e preços', () => `${bt('Novo serviço', () => fServico({}), 'p', 'add')}<div class="card lista">${S.db['Serviços'].map(s => `<button type="button" class="item" ${on(() => fServico(s))}><span class="cresce"><span class="t">${esc(s['Serviço'])}</span><br><span class="mut peq">${esc([s.Tipo, s['Duração'] !== '' ? s['Duração'] + ' min' : '', s.Regra].filter(Boolean).join(' · '))}</span></span><b class="num">${s['Preço'] === '' ? 'Consultar' : rs(s['Preço'])}</b>${s.Ativo === 'Não' ? tag('Inativo') : ''}</button>`).join('')}</div>`); }
function fServico(s) { janela(s.ID ? 'Editar serviço' : 'Novo serviço', () => `${s.ID ? `<h2>${esc(s['Serviço'])}</h2>` : campo('z1', 'Serviço', '')}<div class="duo">${escolha('z2', 'Tipo', s.Tipo || 'Principal', ['Principal', 'Adicional'])}${escolha('z3', 'Espécie', s['Espécie'], ['Cachorro', 'Gato', 'Exótico'], 'Todas')}${escolha('z4', 'Porte', s.Porte, ['Pequeno', 'Médio', 'Grande'], 'Todos')}${campo('z6', 'Duração (min)', s['Duração'], 'number', 'min="0" step="5"')}${reais('z5', 'Preço (vazio = consultar)', s['Preço'])}${escolha('z7', 'Regra', s.Regra || 'Fixo', ['Fixo', 'A partir de', 'Consultar'])}</div>${escolha('z8', 'Situação', s.Ativo || 'Sim', [['Sim', 'Ativo'], ['Não', 'Inativo']])}<div class="rod">${bt('Voltar', fServicos)}${bt('Salvar', b => trabalhar(b, async () => { const o = { Tipo: val('z2'), 'Espécie': val('z3'), Porte: val('z4'), 'Preço': lerReais(val('z5')), 'Duração': num(val('z6')), Regra: val('z7'), Ativo: val('z8') }; if (s.ID) o.ID = s.ID; else { exigir(val('z1') && !servico(val('z1')), 'Informe um nome ainda não usado.'); o['Serviço'] = val('z1'); } await salvar([{ aba: 'Serviços', obj: o }], 'Serviço salvo'); fServicos(); }), 'p')}</div>`); }
function fRegioes() { janela('Bairros e regiões', () => `${bt('Novo bairro', () => fRegiao({}), 'p', 'add')}<div class="card lista">${S.db['Regiões'].map(r => `<button type="button" class="item" ${on(() => fRegiao(r))}><span class="cresce"><span class="t">${esc(r.Bairro)}</span><br><span class="mut peq">${esc([r['Região'], r.Dias, num(r.Adicional) ? '+' + rs(r.Adicional) : ''].filter(Boolean).join(' · '))}</span></span>${tag(r.Atende || 'A confirmar', r.Atende === 'Sim' ? 'ok' : r.Atende === 'Não' ? 'rd' : 'am')}</button>`).join('') || vazio('Nenhum bairro cadastrado.', 'rota')}</div>`); }
function fRegiao(r) { const m = new Set(String(r.Dias || '').split(',').map(s => s.trim()).filter(Boolean)); janela(r.ID ? 'Editar bairro' : 'Novo bairro', () => `${campo('g1', 'Bairro', r.Bairro)}${campo('g2', 'Região', r['Região'], 'text', 'placeholder="Ex.: Leste"')}<div><p class="forte peq" style="margin-bottom:8px">Dias de atendimento</p><div class="chips">${['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map(d => `<button type="button" class="chip ${m.has(d) ? 'on' : ''}" ${on(b => { m.has(d) ? m.delete(d) : m.add(d); b.classList.toggle('on', m.has(d)); })}>${d}</button>`).join('')}</div></div><div class="duo">${escolha('g3', 'Atende', r.Atende || 'Sim', ['Sim', 'Não', 'A confirmar'])}${reais('g4', 'Adicional', r.Adicional)}</div><div class="rod">${bt('Voltar', fRegioes)}${bt('Salvar', b => trabalhar(b, async () => { exigir(val('g1'), 'Informe o bairro.'); const o = { Bairro: val('g1'), 'Região': val('g2'), Dias: ['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].filter(d => m.has(d)).join(', '), Atende: val('g3'), Adicional: lerReais(val('g4')) }; if (r.ID) o.ID = r.ID; await salvar([{ aba: 'Regiões', obj: o }], 'Bairro salvo'); fRegioes(); }), 'p')}</div>`); }

// ---------- celular ----------
// Botão Voltar: fecha a janela, depois volta ao Início e só então sai do app.
history.pushState({ app: 1 }, '');
addEventListener('popstate', () => {
  if ($('janela').open) { fecha(); history.pushState({ app: 1 }, ''); }
  else if (S.db && S.rota !== 'inicio') { ir('inicio'); history.pushState({ app: 1 }, ''); }
  else history.back();
});
// Ao voltar para o app depois de 2 minutos, busca o que a outra pessoa lançou.
let saiu = 0;
document.addEventListener('visibilitychange', () => {
  if (document.hidden) { saiu = Date.now(); return; }
  if (S.db && saiu && Date.now() - saiu > 120000 && !$('janela').open) carregar().catch(e => aviso(e.message));
});

// ---------- início ----------
(async function () {
  try { S.token = localStorage.getItem('ff_sessao') || ''; } catch (e) { S.token = ''; }
  if (S.token) await abrirApp(); else telaEntrada();
})();
